using System.Text.Json;

namespace QuickExcel.Scripting;

/// <summary>
/// The generated capability manifest. It lists only implemented members; every
/// other member of the full type skeleton is rejected by the script proxy and
/// by the host before any workbook state is touched. Generated by
/// tools/QuickExcel.ApiGen and never edited by hand.
/// </summary>
public sealed class ScriptCapabilities
{
    public const string ResourceName = "QuickExcel.Scripting.capabilities.json";
    // Capability contract shared by file APIs v3/v4, not the current workbook API version.
    public const int ApiVersion = 3;

    private readonly Dictionary<string, HashSet<int>> _hostArities;
    private readonly Dictionary<string, int> _costs;
    private readonly HashSet<(string Method, int Arity)> _selectedHost;

    public static ScriptCapabilities Current { get; } = Load();

    private ScriptCapabilities(string json, string sourceSha256, Dictionary<string, HashSet<int>> hostArities, Dictionary<string, int> costs,
        HashSet<(string Method, int Arity)> selectedHost)
    {
        Json = json;
        SourceSha256 = sourceSha256;
        _hostArities = hostArities;
        _costs = costs;
        _selectedHost = selectedHost;
    }

    /// <summary>The exact manifest JSON embedded for the script proxy.</summary>
    public string Json { get; }

    /// <summary>SHA-256 of the pinned Office Scripts declaration the manifest was generated from.</summary>
    public string SourceSha256 { get; }

    /// <summary>True when <paramref name="method"/> is an implemented host method with this argument count.</summary>
    public bool AllowsHost(string method, int arity) =>
        _hostArities.TryGetValue(method, out var arities) && arities.Contains(arity);

    public bool AllowsSelectedHost(string method, int arity) => _selectedHost.Contains((method, arity));

    /// <summary>Per-call weight declared for a host method, or 0 when it is not implemented.</summary>
    public int MaxCost(string method) => _costs.TryGetValue(method, out var cost) ? cost : 0;

    public static ScriptCapabilities Load()
    {
        using var stream = typeof(ScriptCapabilities).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException("缺少脚本能力清单：" + ResourceName);
        using var reader = new StreamReader(stream);
        var json = reader.ReadToEnd();
        using var document = JsonDocument.Parse(json);
        var root = document.RootElement;
        if (root.ValueKind != JsonValueKind.Object || !root.TryGetProperty("apiVersion", out var version) ||
            version.ValueKind != JsonValueKind.Number || !version.TryGetInt32(out var api) || api != ApiVersion)
            throw new InvalidOperationException("脚本能力清单版本不受支持。");
        if (!root.TryGetProperty("source", out var source) || source.ValueKind != JsonValueKind.Object ||
            !source.TryGetProperty("sha256", out var hash) || hash.ValueKind != JsonValueKind.String ||
            string.IsNullOrWhiteSpace(hash.GetString()))
            throw new InvalidOperationException("脚本能力清单缺少来源校验值。");
        if (!root.TryGetProperty("types", out var types) || types.ValueKind != JsonValueKind.Object)
            throw new InvalidOperationException("脚本能力清单缺少类型定义。");

        var arities = new Dictionary<string, HashSet<int>>(StringComparer.Ordinal);
        var costs = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var type in types.EnumerateObject())
        {
            if (type.Value.ValueKind != JsonValueKind.Object ||
                !type.Value.TryGetProperty("members", out var members) || members.ValueKind != JsonValueKind.Object)
                throw new InvalidOperationException("脚本能力清单成员结构无效：" + type.Name);
            foreach (var member in members.EnumerateObject())
            {
                if (member.Value.ValueKind != JsonValueKind.Object ||
                    !member.Value.TryGetProperty("kind", out var kind) || kind.ValueKind != JsonValueKind.String)
                    throw new InvalidOperationException("脚本能力清单成员无效：" + type.Name + "." + member.Name);
                switch (kind.GetString())
                {
                    case "local":
                        if (member.Value.TryGetProperty("host", out _) || member.Value.TryGetProperty("arity", out _))
                            throw new InvalidOperationException("本地成员不能声明宿主方法：" + type.Name + "." + member.Name);
                        break;
                    case "host":
                        if (!member.Value.TryGetProperty("host", out var host) || host.ValueKind != JsonValueKind.String ||
                            string.IsNullOrWhiteSpace(host.GetString()) ||
                            !member.Value.TryGetProperty("arity", out var arity) || arity.ValueKind != JsonValueKind.Number ||
                            !arity.TryGetInt32(out var count) || count is < 0 or > 8)
                            throw new InvalidOperationException("宿主成员定义无效：" + type.Name + "." + member.Name);
                        var method = host.GetString()!;
                        if (!arities.TryGetValue(method, out var allowed)) arities[method] = allowed = [];
                        allowed.Add(count);
                        var cost = 0;
                        if (member.Value.TryGetProperty("cost", out var declared) && declared.ValueKind == JsonValueKind.Number &&
                            declared.TryGetInt32(out var value) && value >= 0) cost = value;
                        costs[method] = Math.Max(costs.GetValueOrDefault(method), cost);
                        break;
                    default:
                        throw new InvalidOperationException("未知的成员种类：" + type.Name + "." + member.Name);
                }
            }
        }
        if (arities.Count == 0) throw new InvalidOperationException("脚本能力清单没有宿主成员。");
        var selectedHost = new HashSet<(string, int)>();
        foreach (var type in root.GetProperty("selectedModel").EnumerateObject())
        {
            var members = types.GetProperty(type.Name).GetProperty("members");
            foreach (var item in type.Value.EnumerateArray())
            {
                var member = members.GetProperty(item.GetString()!);
                if (member.GetProperty("kind").GetString() == "host")
                    selectedHost.Add((member.GetProperty("host").GetString()!, member.GetProperty("arity").GetInt32()));
            }
        }
        return new ScriptCapabilities(json, hash.GetString()!, arities, costs, selectedHost);
    }
}
